def logger(func):
    def wrapper(*args, **kwargs):
        print(f"--- {func.__name__} 시작 ---")
        result = func(*args, **kwargs)
        print(f"--- {func.__name__} 종료 ---")
        return result
    return wrapper

@logger
def say_hello(name):
    print(f"안녕하세요, {name}님!")

say_hello("앨리스")
